-- Smart Hospital: demo data for every module (fictional people, places and numbers).
-- LOCAL / DEMO DATABASE ONLY. Never run against the live hospital database.
--
-- What it creates (dates are relative to the day you run it, so dashboards look current):
--   Staff (14, all roles)  login: <first>.<last>@example.com / Demo@123  e.g. anil.deshpande@example.com (doctor)
--   Patients (19)          patient panel: pat7001 .. pat7019 / demo123
--   Appointments, OPD visits with full prescriptions (ICD-10 diagnosis, medicines, tests, advice, follow-up), IPD admissions (current + discharged) with beds, charges,
--   nurse notes, consultant instructions, discharge cards, operation theatre, birth/death records,
--   pharmacy purchases/stock/sales, pathology + radiology bills with reports, blood bank donors/components/issues,
--   ambulance, front office (visitors, calls, complaints, postal), income/expenses, inventory, attendance,
--   leave, payroll, referrals and events.
--
-- Master/lookup rows (departments, charges, beds, medicines, tests...) are matched by name and reused if they
-- already exist; they are kept on re-run. Everything else uses fixed ids from 7001 up and is replaced on re-run.
-- Run:  mysql -u <user> -p <database> < DEMO_SEED_ALL_MODULES.sql

SET NAMES utf8mb4;
SET @today = CURDATE();

-- Safety: stop if ids this seed uses already hold non-demo patients or staff (demo rows use @example.com emails).
SELECT IF((SELECT COUNT(*) FROM patients WHERE id BETWEEN 7001 AND 7019 AND email NOT LIKE '%@example.com') + (SELECT COUNT(*) FROM staff WHERE id BETWEEN 7001 AND 7014 AND email NOT LIKE '%@example.com') = 0, 'ok', (SELECT 'ABORT: ids 7001+ hold real patients/staff - do not run on this database' UNION SELECT 'x')) AS safety_check;

START TRANSACTION;
SET FOREIGN_KEY_CHECKS = 0;

-- Free beds held by a previous run, then remove its rows
UPDATE bed b JOIN ipd_details i ON i.bed = b.id SET b.is_active = 'yes' WHERE i.id BETWEEN 7001 AND 7006;
